// npm run gen: lib/game/palette.dart → src/ui/generated/palette.ts. dart:ui does not run in the
// Dart VM, so the colours are read from the source instead of dumped; test/config-sync.test.ts
// fails when the generated file drifts.
import { readFileSync, writeFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';

const src = fileURLToPath(new URL('../../lib/game/palette.dart', import.meta.url));
const dst = fileURLToPath(new URL('../src/ui/generated/palette.ts', import.meta.url));

export const ROLES = ['bg', 'bgAlt', 'primary', 'secondary', 'accent', 'hazard', 'glow'] as const;

export function renderPalette(dart: string): string {
  const blocks = [...dart.matchAll(/static const (\w+) = Palette\(([\s\S]*?)\);/g)];
  if (blocks.length === 0) throw new Error('no palettes found in palette.dart');
  const out = blocks.map(([, id, body]) => {
    const name = /name: '([^']+)'/.exec(body)?.[1];
    if (!name) throw new Error(`palette ${id}: no name`);
    const roles = ROLES.map((r) => {
      const m = new RegExp(`\\b${r}: Color\\(0x([0-9A-Fa-f]{8})\\)`).exec(body);
      if (!m) throw new Error(`palette ${id}: no ${r}`);
      return `${r}: 0x${m[1].toUpperCase()}`;
    });
    return `  ${id}: { name: '${name}', ${roles.join(', ')} },`;
  });
  return `// GENERATED by scripts/gen-palette.ts from lib/game/palette.dart — do not edit.\n// ARGB, as in Dart's Color(0xAARRGGBB).\nexport const PALETTES = {\n${out.join('\n')}\n} as const;\n`;
}

export const paletteSource = (): string => renderPalette(readFileSync(src, 'utf8'));

if (process.argv[1] === fileURLToPath(import.meta.url)) {
  writeFileSync(dst, paletteSource());
  console.log(`wrote ${dst}`);
}
